import React, { useState, useMemo } from "react";

function Meals() {
  const [search, setSearch] = useState("");
  const [year, setYear] = useState("");

  const filteredData = useMemo(() => {
    const words = search
      .toLowerCase()
      .split(/\s+/)
      .filter(Boolean);

    const result = data.filter(item => {
      const text = `${item.title} ${item.course} ${item.college}`.toLowerCase();

      const matchesSearch =
        words.length === 0 ||
        words.every(word => text.includes(word));

      const matchesYear =
        !year || item.admission_year === year;

      return matchesSearch && matchesYear;
    });

    // ✅ limit to 100 when no search
    if (words.length === 0) {
      return result.slice(0, 100);
    }

    return result;
  }, [search, year, data]);

  return (
    <div style={{ padding: 20, maxWidth: 800, margin: "auto" }}>
      
      {/* Search + Filter */}
      <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
        
        <input
          type="text"
          placeholder="Search (multi-word)..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{ flex: 1, padding: 8 }}
        />

        <select value={year} onChange={(e) => setYear(e.target.value)}>
          <option value="">All Years</option>
          {[2020, 2021, 2022, 2023, 2024, 2025].map(y => (
            <option key={y} value={String(y)}>
              {y}
            </option>
          ))}
        </select>
      </div>

      {/* Info */}
      {search.trim() === "" && (
        <p style={{ fontSize: 12, color: "#666" }}>
          Showing first 100 results. Use search to see more.
        </p>
      )}

      {/* Results */}
      <div>
        {filteredData.length === 0 && <p>No results found</p>}

        {filteredData.map((item, index) => (
          <div
            key={index}
            style={{
              background: "white",
              border: "1px solid #ddd",
              padding: 12,
              marginBottom: 10,
              borderRadius: 6
            }}
          >
            <h4 style={{ margin: "0 0 6px" }}>{item.title}</h4>

            <p style={{ margin: 0 }}>
              <strong>Course:</strong> {item.course}
            </p>

            <p style={{ margin: 0 }}>
              <strong>College:</strong> {item.college}
            </p>

            <p style={{ margin: 0 }}>
              <strong>Year:</strong> {item.admission_year}
            </p>

            <a href={item.link} target="_blank" rel="noreferrer">
              View / Print
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}

